from confluent_kafka import Consumer, KafkaException

conf = {
    "bootstrap.servers": "localhost:9092",
    "group.id": "lake-sink",
    "enable.auto.commit": False,      # commit explicitly for precise semantics
    "auto.offset.reset": "earliest",
}
consumer = Consumer(conf)
consumer.subscribe(["cdc.public.orders"])

AT_LEAST_ONCE = True  # flip to False to see at-most-once

try:
    while True:
        msg = consumer.poll(1.0)
        if msg is None:
            continue
        if msg.error():
            raise KafkaException(msg.error())

        if AT_LEAST_ONCE:
            upsert_to_lake(msg)          # side effect FIRST
            consumer.commit(msg)         # commit AFTER success -> at-least-once
            # crash between the two lines => reprocess (duplicate, absorbed by upsert)
        else:
            consumer.commit(msg)         # commit BEFORE processing -> at-most-once
            upsert_to_lake(msg)          # crash here => record is LOST
finally:
    consumer.close()


